import React, { useState, useEffect } from "react";

const AdmInfAluno = ({ id }) => {
  const [aluno, setAluno] = useState(null);
  const [listaCursos, setListaCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [editMode, setEditMode] = useState(false);

  useEffect(() => {
    // Carregar informações do aluno
    const fetchAluno = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAluno(dados);
          setCursoSelecionado(dados.cursoId || ""); // Preencher com o curso atual do aluno
        }
      } catch (error) {
        console.error("Erro ao buscar aluno:", error);
      }
    };

    // Carregar lista de cursos
    const fetchCursos = async () => {
      try {
        const resposta = await fetch("http://localhost:5000/cursos");
        if (resposta.ok) {
          const dados = await resposta.json();
          setListaCursos(dados);
        }
      } catch (error) {
        console.error("Erro ao buscar cursos:", error);
      }
    };

    fetchAluno();
    fetchCursos();
  }, [id]);

  const handleSaveClick = async () => {
    if (!cursoSelecionado) return;

    try {
      const resposta = await fetch(`http://localhost:5000/alunos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cursoId: cursoSelecionado }),
      });

      if (resposta.ok) {
        const dadosAtualizados = await resposta.json();
        setAluno(dadosAtualizados);
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro ao atualizar curso:", error);
    }
  };

  if (!aluno) {
    return <p>Carregando dados do aluno...</p>;
  }

  return (
    <div>
      <h2>Informações do Aluno</h2>
      <p>
        <strong>Nome:</strong> {aluno.nome}
      </p>
      <p>
        <strong>Email:</strong> {aluno.email}
      </p>
      <p>
        <strong>Morada:</strong> {aluno.morada}
      </p>
      <p>
        <strong>Contato:</strong> {aluno.contacto}
      </p>
      <p>
        <strong>Curso Atual:</strong>{" "}
        {aluno.curso ? aluno.curso.nome : "Nenhum"}
      </p>

      {editMode ? (
        <div>
          <label>Selecionar Curso:</label>
          <select
            className="form-control mb-2"
            value={cursoSelecionado}
            onChange={(e) => setCursoSelecionado(e.target.value)}
          >
            <option value="">Selecione um curso</option>
            {listaCursos.map((c) => (
              <option key={c.id} value={c.id}>
                {c.nome}
              </option>
            ))}
          </select>
          <button onClick={handleSaveClick} className="btn btn-success">
            Salvar
          </button>
          <button
            onClick={() => setEditMode(false)}
            className="btn btn-secondary"
          >
            Cancelar
          </button>
        </div>
      ) : (
        <button onClick={() => setEditMode(true)} className="btn btn-primary">
          Editar Curso
        </button>
      )}
    </div>
  );
};

export default AdmInfAluno;
